using System.Collections.Generic;
using SWLOR.Game.Server.Feature.ShipDefinition;
using SWLOR.Game.Server.Feature.ShipModuleDefinition;
using SWLOR.Game.Server.Service.CraftService;
using SWLOR.Game.Server.Service.SkillService;

namespace SWLOR.Game.Server.Feature.RecipeDefinition.EngineeringRecipeDefinition
{
    /// <summary>
    /// Recipes for the space revamp catalog: every module step in <see cref="RevampModuleCatalog"/>
    /// and every hull deed in <see cref="RevampShipCatalog"/>. The catalogs are generated by
    /// tools/SpaceRevampBalance/catalog.py; the Design Bible Engineering Recipes rows by bible_recipes.py.
    /// </summary>
    public class RevampStarshipRecipes: IRecipeListDefinition
    {
        private readonly RecipeBuilder _builder = new();

        public Dictionary<RecipeType, RecipeDetail> BuildRecipes()
        {
            foreach (var step in RevampModuleCatalog.Steps)
            {
                var recipe = _builder.Create(step.RecipeType, SkillType.Engineering)
                    .Category(RecipeCategoryType.ShipModule)
                    .Resref(step.Tag)
                    .Level(step.RecipeLevel)
                    .Quantity(1)
                    .EnhancementSlots(RecipeEnhancementType.Module, 1);

                foreach (var (resref, quantity) in step.Components)
                {
                    recipe.Component(resref, quantity);
                }
            }

            foreach (var hull in RevampShipCatalog.Hulls)
            {
                var recipe = _builder.Create(hull.RecipeType, SkillType.Engineering)
                    .Category(RecipeCategoryType.Starship)
                    .Resref(hull.Tag)
                    .Level(hull.RecipeLevel)
                    .Quantity(1)
                    .EnhancementSlots(RecipeEnhancementType.Starship, 1);

                foreach (var (resref, quantity) in hull.Components)
                {
                    recipe.Component(resref, quantity);
                }
            }

            return _builder.Build();
        }
    }
}
